/*	name:	audit.h	type:	MPW C++ 3.2		This if the interface to the audit package.Programmers:AGR	Arthur RymanChange History:AGR	V100	1992/09/21	Split from main:util.h.AGR	V101	1994/10/13	Add audit log file.AGR	V102	1994/10/16	Add brackets to audit enter/exit so MPW can select scope.AGR	V103	1995/08/05	Use NAUDIT to unconditionally disable auditing.*/#include <iostream.h>		// V101#include <fstream.h>		// V101// define NAUDIT here to disable auditing for the entire application.// define AUDIT in each source file to control auditing for that file.#define NAUDIT 1// V103#if	!defined(NAUDIT) && defined(AUDIT) && AUDITextern char auditStr[256];extern ofstream auditLog;	// V101#define auditEnter(a)			char *auditName = a;audit1("{Entered.")//#define audit1(a)				{ostrstream(auditStr,sizeof(auditStr)) << auditName << ": "\//										<< a << ends; debugstr(auditStr);}#define audit1(a)				auditLog << auditName << ": " << a << endl;#define audit2(a,b)				audit1(a << b)#define audit3(a,b,c)			audit1(a << b << c)#define audit4(a,b,c,d)			audit1(a << b << c << d)#define audit5(a,b,c,d,e)		audit1(a << b << c << d << e)#define audit6(a,b,c,d,e,f)		audit1(a << b << c << d << e << f)#define auditExit()				audit1("Exited.}")#else#define auditEnter(a)#define audit1(a)#define audit2(a,b)#define audit3(a,b,c)#define audit4(a,b,c,d)#define audit5(a,b,c,d,e)#define audit6(a,b,c,d,e,f)#define auditExit()#endif